export function SimpleHero({ eyebrow, title, copy, children }: { eyebrow?: string; title: string; copy: string; children?: React.ReactNode }) { return <section className="bg-[var(--surface)]"><div className="mx-auto max-w-[1320px] px-5 py-16 lg:px-8 lg:py-24"><div className="max-w-3xl">{eyebrow && <p className="mb-4 text-xs font-bold uppercase tracking-[0.18em] text-[var(--teal)]">{eyebrow}</p>}<h1 className="text-balance text-4xl font-bold tracking-tight text-[var(--navy)] md:text-5xl">{title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-[var(--muted-text)]">{copy}</p>{children}</div></div></section> }

export function StatsPreview() { return <div className="rounded-2xl bg-white p-5 shadow-[0_20px_50px_rgba(13,43,78,0.12)]"><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-[var(--muted-text)]">Corporate overview</p><p className="mt-1 text-sm font-semibold text-[var(--navy)]">May 2026 · Concept preview</p></div><div className="grid size-9 place-items-center rounded-lg bg-[var(--light-teal)] text-[var(--teal)]"><BriefcaseBusiness className="size-4" /></div></div><div className="grid grid-cols-3 gap-3">{[['Active employees','184'],['Visits this month','612'],['Districts used','9']].map(([l,v]) => <div key={l} className="rounded-xl bg-[var(--surface)] p-3"><p className="text-lg font-bold text-[var(--navy)]">{v}</p><p className="mt-1 text-[10px] text-[var(--muted-text)]">{l}</p></div>)}</div><div className="mt-4 flex items-center justify-between rounded-xl bg-[var(--light-blue)] px-4 py-3"><span className="text-xs font-semibold text-[var(--navy)]">Estimated commute time saved</span><strong className="text-sm text-[var(--dark-teal)]">1,284 hrs</strong></div></div> }

export function WorkspacePreview() { return <div className="rounded-2xl border border-[var(--border)] bg-white p-4 shadow-sm"><div className="flex items-center gap-3"><img src={spaces[0].image} alt="Workspace listing preview" className="size-16 rounded-xl object-cover" /><div><p className="text-xs font-bold uppercase tracking-widest text-[var(--teal)]">Your listing on GoWork</p><h3 className="mt-1 font-bold text-[var(--navy)]">Fabrika Coworking</h3><p className="text-xs text-[var(--muted-text)]">Yasamal · Verified partner</p></div></div><div className="mt-4 grid grid-cols-3 gap-2 text-center text-xs"><div className="rounded-lg bg-[var(--surface)] p-2"><strong className="block text-[var(--navy)]">38</strong><span className="text-[var(--muted-text)]">views</span></div><div className="rounded-lg bg-[var(--surface)] p-2"><strong className="block text-[var(--navy)]">12</strong><span className="text-[var(--muted-text)]">requests</span></div><div className="rounded-lg bg-[var(--surface)] p-2"><strong className="block text-[var(--navy)]">87%</strong><span className="text-[var(--muted-text)]">capacity</span></div></div></div> }

