export function ValueSection() { return <section className="mx-auto max-w-[1320px] px-5 py-16 lg:px-8"><div className="grid gap-8 md:grid-cols-4">{features.map((item) => <div key={item.title}><FeatureIcon icon={item.icon} /><h3 className="mt-4 font-bold text-[var(--navy)]">{item.title}</h3><p className="mt-2 text-sm leading-6 text-[var(--muted-text)]">{item.copy}</p></div>)}</div></section> }

export function CTABand() { return <section className="bg-[var(--navy)]"><div className="mx-auto flex max-w-[1320px] flex-col gap-6 px-5 py-14 md:flex-row md:items-center md:justify-between lg:px-8"><div><h2 className="text-3xl font-bold text-white">Work closer to where life already takes you.</h2><p className="mt-2 text-white/65">Discover your next productive place in Baku.</p></div><div className="flex flex-wrap gap-3"><Link href="/spaces" className="rounded-lg bg-[var(--teal)] px-5 py-3 text-sm font-bold text-white">Find a Workspace</Link><Link href="/for-partners" className="rounded-lg border border-white/20 px-5 py-3 text-sm font-bold text-white">Become a Partner</Link></div></div></section> }

