export function PriceCards() { return <div className="grid gap-4 md:grid-cols-4">{[['Student','For occasional study and group work.','5–8 visits concept'],['Standard','For regular hybrid workers.','15–20 visits concept'],['Unlimited','For frequent remote workers.','Fair-use access'],['Corporate','For companies and their employees.','Per-employee plans']].map(([name,copy,usage], i) => <div key={name} className={`rounded-2xl border p-6 ${i === 1 ? 'border-[var(--teal)] bg-[var(--light-teal)]' : 'border-[var(--border)] bg-white'}`}><h3 className="text-xl font-bold text-[var(--navy)]">{name}</h3><p className="mt-3 min-h-12 text-sm leading-6 text-[var(--muted-text)]">{copy}</p><div className="my-6 border-y border-[var(--border)] py-4"><p className="text-sm font-bold text-[var(--teal)]">Coming soon</p><p className="mt-1 text-xs text-[var(--muted-text)]">{usage}</p></div><Link href="/contact" className="flex items-center justify-between text-sm font-bold text-[var(--navy)]">Get updates <ArrowRight className="size-4" /></Link></div>)}</div> }

